      'help.chatArchived.title': 'Chat archiviate',
      'help.chatArchived.text': 'Archiviare una chat la toglie dall’elenco senza cancellarla. Da qui si entra nell’elenco delle chat archiviate; lì il pulsante Ripristina, sotto l’elenco, riporta una chat tra le altre.',
      'help.sharedMemory.title': 'Memorie condivise',
      'help.sharedMemory.text': 'Note che il modello riceve in tutte le chat, raccolte in un dossier: profilo, preferenze, progetti attivi. I progetti di Code entrano nel dossier da soli; le altre voci si scrivono qui o si salvano quando il modello le propone.',
      'help.chatMaster.title': 'Master attivo',
      'help.chatMaster.text': 'Il modello che risponde in questa chat, con il suo identificativo su OpenRouter. Un clic apre i modelli e i parametri di questa chat: quello che scegli lì vale solo qui; il resto viene dalle Impostazioni.',
      'help.artifacts.title': 'Artefatti',
      'help.artifacts.text': 'I file prodotti in questa chat, cioè immagini, video, audio, report e archivi, salvati nel workspace del suo container. Da qui si aprono e si scaricano.',
      'help.chatMemory.title': 'Memoria della chat',
      'help.chatMemory.text': 'I riassunti dei turni di questa chat. Quando la conversazione supera il tetto di contesto, le parti vecchie arrivano al modello riassunte. Da qui si leggono, si correggono e si impostano valori propri per questa chat.',
      'help.chatEnv.title': 'Ambiente della chat',
      'help.chatEnv.text': 'Il container Podman in cui il modello esegue codice e comandi per questa chat. Nel container c’è solo il volume della chat, sul disco dei pod: quello che il modello scrive lì compare nella cartella workspace della chat, e quello che carichi tu va nel volume. «Isolato» vuol dire senza accesso a Internet; l’accesso si attiva dalla finestra che si apre.',
      'help.chatTools.title': 'Tool e deleghe',
      'help.chatTools.text': 'Nativi sono i tool che il Master svolge da sé; delegati quelli affidati a un modello specifico, per esempio immagini o voce. La matita su ogni tool sceglie un modello solo per questa chat.',
      'help.stt.title': 'Dettatura',
      'help.stt.text': 'Registra dal microfono e scrive il testo nel campo del messaggio. Un secondo clic ferma la registrazione.',
      'help.tts.title': 'Lettura ad alta voce',
      'help.tts.text': 'Legge questa risposta con il modello assegnato al ruolo Sintesi vocale.',
      'help.roleStatus.title': 'Ruoli e stato',
      'help.roleStatus.text': 'Ogni voce è un ruolo o un tool; sotto il nome c’è il modello assegnato. Nativo: il Master svolge il tool da sé. Delegato: il tool usa un modello specifico. Non impostato: nessun modello assegnato.',
      'help.catalogSync.title': 'Catalogo modelli',
      'help.catalogSync.text': 'L’elenco dei modelli, con prezzi e capacità, viene da OpenRouter. Questo pulsante lo scarica di nuovo; accanto c’è la data dell’ultimo aggiornamento.',
      'help.filters.title': 'Ricerca e filtri',
      'help.filters.text': 'L’elenco contiene solo i modelli compatibili con il ruolo selezionato. Si cerca per nome o fornitore, si filtra per provider e per contesto minimo, si ordina per rilevanza, prezzo, contesto o nome.',
      'help.modelTags.title': 'Caratteristiche del modello',
      'help.modelTags.text': 'Tools: sa chiamare i tool. JSON: rispetta uno schema di output. Reasoning: ragiona prima di rispondere. ctx: i token di contesto che accetta. In / Out: prezzo per milione di token in ingresso e in uscita; Med è la media. Coda: lo sconto se i turni passano dalla coda batch, attivabile nei parametri del ruolo.',
      'help.inspect.title': 'Dettagli del modello',
      'help.inspect.text': 'Apre il pannello con tutti i dati del modello presi dal catalogo di OpenRouter.',
      'help.paramsReset.title': 'Valori predefiniti',
      'help.paramsReset.text': 'I parametri si salvano appena li cambi e valgono per questo modello. Questo pulsante li riporta ai valori predefiniti. Sotto ogni parametro c’è la spiegazione di cosa fa.',
      'help.paramsUnsupported.title': 'Parametri non supportati',
      'help.paramsUnsupported.text': 'Il fornitore di questo modello non accetta questi parametri, quindi non vengono inviati. Con un altro modello l’elenco cambia.',
      'help.promptMode.title': 'Versione del prompt',
      'help.promptMode.text': 'Ogni sezione del prompt di sistema ha una versione corta, che costa meno token, una lunga, con istruzioni più dettagliate, e una personalizzata, cioè il testo che scrivi nel riquadro sotto. Il pulsante di ripristino riporta al testo originale.',
      'help.scanPackages.title': 'Cache dei pacchetti',
      'help.scanPackages.text': 'Rilegge la cartella della cache locale e aggiorna l’elenco. I pacchetti attivi vengono installati nello store condiviso e sono pronti in ogni container, senza reinstallarli.',
      'help.packageFilters.title': 'Filtri dei pacchetti',
      'help.packageFilters.text': 'Mostrano solo i pacchetti Python, solo quelli Node.js o solo quelli predefiniti, cioè disponibili al modello in ogni container.',
      'help.codeKinds.title': 'Locale o Podman',
      'help.codeKinds.text': 'Podman è consigliato per un progetto da zero affidato ad agenti autonomi in sessioni lunghe: il modello lavora in un container isolato e non tocca il computer. Locale va bene per modifiche mirate su una cartella esistente, o quando segui passo passo cosa fa il modello.',
      'help.codeHistory.title': 'Storico',
      'help.codeHistory.text': 'Ogni modifica al progetto viene registrata da sola con git, sul computer. Lo storico mostra i passi uno per uno, con i file cambiati.',
      'help.codePerms.title': 'Permessi del modello',
      'help.codePerms.text': 'Cosa il modello fa senza chiedere. Codice: manuale chiede ogni modifica; semi chiede la prima volta per ogni file e sempre per creare, eliminare o rinominare; automatico non chiede. Terminale: lo stesso per i comandi. L’icona accanto elenca le approvazioni ricordate.',
      'help.codePush.title': 'Carica su GitHub',
      'help.codePush.text': 'Compare quando il progetto è collegato a un repository. Il caricamento su GitHub lo fai solo tu, sul ramo che scegli: il modello non lo fa mai.',
      'help.codeChats.title': 'Chat del progetto',
      'help.codeChats.text': 'Le conversazioni su questo progetto. Qui il modello ha i tool per leggere e modificare i file del progetto; il pulsante + apre una nuova chat.',
      'help.codeAi.title': 'Pannello dell’AI',
      'help.codeAi.text': 'Mostra o nasconde la chat del progetto accanto all’editor.',
