      'realtime.phoneHint': 'Collega il telefono a questo computer per parlare con {name}, seguire i progetti, dare compiti ai Master e rispondere alle loro richieste quando sei lontano. Il collegamento passa dalla rete I2P: è cifrato da un capo all\'altro e nessuno dei due dispositivi rivela il proprio indirizzo di rete. Con il collegamento acceso funziona mentre SynthOrg è aperto, con il servizio acceso anche quando la sua finestra è chiusa.',
