      'realtime.phoneLoading': 'Reading the state of the bridge…',
      'realtime.phoneLocked': 'The database is locked: unlock it to use the phone bridge.',
      'realtime.phoneHint': 'Connect your phone to this computer to talk with {name}, follow the projects, give tasks to the Masters and answer their requests when you are away. The connection goes through the I2P network: it is encrypted end to end and neither device reveals its network address. With the connection on it works while SynthOrg is open, with the service on also when its window is closed.',
      'realtime.phoneOn': 'Connection: with the app open',
      'realtime.phoneOnHint': 'On: while SynthOrg is open the paired phones can reach it. Off: with the app open the bridge stays off.',
      'realtime.phoneLan': 'Direct connection on the local network',
      'realtime.phoneLanHint': 'When phone and computer are on the same local network they connect directly, without going through I2P: much faster. The content stays encrypted, but whoever runs the network sees that the two devices talk. Off, everything always goes through I2P.',
      'realtime.phoneLanListening': 'Listening on the local network only: {where}',
      'realtime.phoneLanWaiting': 'Listening when the bridge is on and a phone is paired, on a local network.',
      'realtime.phoneLanOn': 'Direct connection on the local network turned on.',
      'realtime.phoneLanOff': 'Direct connection on the local network turned off: everything goes through I2P.',
      'realtime.phoneDeviceConnectedLan': 'Connected over the local network',
      'realtime.phoneHops': 'Length of the I2P tunnels',
      'realtime.phoneHopsHint': 'How many routers of the I2P network stand between this computer and the phone, each way. With one hop a request takes a fraction of the time three take; with three no router of the network knows who talks to whom. No third-party server and no open port, whatever the number. Changing it rebuilds the tunnels: it takes a few seconds.',
      'realtime.phoneHops1': '1 hop: fast, less cover',
      'realtime.phoneHops2': '2 hops',
      'realtime.phoneHops3': '3 hops: the full cover of I2P, slow',
      'realtime.phoneHopsSet': 'I2P tunnels of {hops} hops: the bridge rebuilds them.',
      'realtime.phoneService': 'Service: with the app closed',
      'realtime.phoneServiceHint': 'On: when you close the window SynthOrg keeps running without a window and the paired phones can reach it. An icon stays in the notification area, to open it again or close it for good. Off: closing the window closes SynthOrg and the bridge.',
      'realtime.phoneAutostart': 'Start with the computer',
